contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 drugs) public payable {
        require(drugs > 0);

        bool reverted;
        c.seedMarket(drugs); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        bool initAfter = c.initialized(); if (__ESBMC_reverted()) return;
        uint256 marketAfter = c.marketDrugs(); if (__ESBMC_reverted()) return;

        assert(reverted || (initAfter == true && marketAfter == drugs));
    }

    receive() external payable {}
}

