pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 drugs) internal {
        vm.assume(drugs > 0);
        bool reverted;
        try c.seedMarket(drugs) { reverted = false; } catch { reverted = true; }
        bool initAfter;
        try c.initialized() returns (bool __r) { initAfter = __r; } catch { return; }
        uint256 marketAfter;
        try c.marketDrugs() returns (uint256 __r) { marketAfter = __r; } catch { return; }
        assertTrue(reverted || (initAfter == true && marketAfter == drugs));
    }

    function testFuzz_run(uint256 drugs) public {
        _run(drugs);
    }

    receive() external payable {}
}
